  int n = sizeof(arr)/sizeof(arr[0]);
  printf("Array original: \n");
  for (int i=0; i < n; i++)
    printf("%d ", arr[i]);
  printf("\n");

  bubbleSort(arr, n);

  printf("Array ordenado: \n");
  for (int i=0; i < n; i++)
    printf("%d ", arr[i]);
  printf("\n");
  return 0;
}

